def are_numbers_closer_than_threshold(numbers, threshold):
    """
    Checks if any two numbers in a list are closer than a given threshold
    by sorting the list and comparing adjacent elements.
    """
    if len(numbers) < 2:
        return False

    sorted_numbers = sorted(numbers)

    return any(
        abs(sorted_numbers[i] - sorted_numbers[i + 1]) < threshold
        for i in range(len(sorted_numbers) - 1)
    )

