def count_nums(nums):
    """
    Count how many numbers in `nums` are greater than 10 and have
    an odd first digit and an odd last digit.
    """
    def first_digit(n):
        return int(str(abs(n))[0])

    def last_digit(n):
        return abs(n) % 10

    return sum(
        1
        for n in nums
        if n > 10
        and first_digit(n) % 2 == 1
        and last_digit(n) % 2 == 1
    )

