def count_numbers(numbers):
    """
    Count numbers in a list where value > 10 and both first and last digits are odd.
    """
    def is_odd_digit(d):
        return d in {1, 3, 5, 7, 9}

    def get_first_and_last(n):
        n = abs(n)
        if n == 0:
            return (0, 0)
        last = n % 10
        while n >= 10:
            n //= 10
        first = n
        return (first, last)

    return sum(
        1 for num in numbers
        if num > 10 and is_odd_digit(get_first_and_last(num)[0]) and is_odd_digit(get_first_and_last(num)[1])
    )

